inline bool active(int scene) {
  return DAYCYCLE_USED && scene >= 0 && scene < SCENE_COUNT &&
         DAYCYCLE_RUNTIMES[scene];
}
inline bool gradeOn(int scene) {
  return DAYCYCLE_USED && scene >= 0 && scene < SCENE_COUNT &&
         DAYCYCLE_GRADES[scene];
}

inline float wrap24(float h) {
  h = fmodf(h, 24.0F);
  return h < 0.0F ? h + 24.0F : h;
}
inline float clampf(float v, float lo, float hi) {
  return v < lo ? lo : (v > hi ? hi : v);
}

// ambience::arcDirection. cos(t)*R + sin(t)*P over a great circle:
// R is the horizon crossing at `rise`, P the tilted peak a quarter
// turn later, and t runs 0..pi above the horizon and on beneath it.
inline void arcDir(float azDeg, float tiltDeg, float rise, float set,
                   float hour, float out[3]) {
  const float az = azDeg * 0.01745329252F;
  const float tilt = clampf(tiltDeg, -89.0F, 89.0F) * 0.01745329252F;
  const float Rx = sinf(az), Rz = cosf(az);
  const float Hx = cosf(az), Hz = -sinf(az);
  const float st = sinf(tilt), ct = cosf(tilt);
  float up = wrap24(set - rise);
  up = clampf(up, 0.25F, 23.75F);
  const float since = wrap24(hour - rise);
  const float t = since <= up ? 3.14159265F * (since / up)
                             : 3.14159265F +
                                   3.14159265F * ((since - up) / (24.0F - up));
  const float c = cosf(t), sn = sinf(t);
  out[0] = c * Rx + sn * st * Hx;
  out[1] = sn * ct;
  out[2] = c * Rz + sn * st * Hz;
  const float l = sqrtf(out[0] * out[0] + out[1] * out[1] + out[2] * out[2]);
  if (l > 1e-6F) {
    out[0] /= l;
    out[1] /= l;
    out[2] /= l;
  } else {
    out[0] = 0.0F, out[1] = 1.0F, out[2] = 0.0F;
  }
}

// ambience::sampleKeys. Cyclic: the last key of the day carries
// through midnight into the first, which is what makes a night that
// spans 00:00 one interval instead of two.
inline void sampleKeys(int scene, float hour, DayKeyData& k) {
  const int first = DAYCYCLE_KEY_FIRSTS[scene];
  const int n = DAYCYCLE_KEY_COUNTS[scene];
  if (n <= 0) return;
  if (n == 1) {
    k = DAY_KEYS[first];
    return;
  }
  const float h = wrap24(hour);
  int hi = 0;
  while (hi < n && wrap24(DAY_KEYS[first + hi].hour) <= h) ++hi;
  const int lo = (hi - 1 + n) % n;
  hi %= n;
  const DayKeyData& a = DAY_KEYS[first + lo];
  const DayKeyData& b = DAY_KEYS[first + hi];
  const float ha = wrap24(a.hour);
  const float span = wrap24(wrap24(b.hour) - ha);
  if (span < 1e-4F) {
    k = a;
    return;
  }
  const float t = clampf(wrap24(h - ha) / span, 0.0F, 1.0F);
  k.hour = h;
  for (int i = 0; i < 3; ++i) {
    k.sky[i] = a.sky[i] + (b.sky[i] - a.sky[i]) * t;
    k.top[i] = a.top[i] + (b.top[i] - a.top[i]) * t;
    k.lit[i] = a.lit[i] + (b.lit[i] - a.lit[i]) * t;
    k.fog[i] = a.fog[i] + (b.fog[i] - a.fog[i]) * t;
  }
  k.amb = a.amb + (b.amb - a.amb) * t;
  k.dif = a.dif + (b.dif - a.dif) * t;
  k.bright = a.bright + (b.bright - a.bright) * t;
  k.stars = a.stars + (b.stars - a.stars) * t;
}

// The whole cycle at `hour`, into the globals above. `grade` false
// skips the drift maths entirely.
inline void evaluate(int scene, float hour) {
  g_hour = wrap24(hour);
  DayKeyData k = DAY_KEYS[0];
  sampleKeys(scene, g_hour, k);
  for (int i = 0; i < 3; ++i) {
    g_sky[i] = k.sky[i];
    g_top[i] = k.top[i];
    g_fog[i] = k.fog[i];
  }
  g_stars = clampf(k.stars, 0.0F, 1.0F);
  const float sunrise = DAYCYCLE_SUNRISES[scene];
  const float sunset = DAYCYCLE_SUNSETS[scene];
  const float moff = DAYCYCLE_MOON_OFFS[scene];
  arcDir(DAYCYCLE_SUN_AZS[scene], DAYCYCLE_SUN_TILTS[scene], sunrise,
         sunset, g_hour, g_sun);
  arcDir(DAYCYCLE_MOON_AZS[scene], DAYCYCLE_MOON_TILTS[scene],
         wrap24(sunrise + moff), wrap24(sunset + moff), g_hour, g_moon);
  const float sunElev = asinf(clampf(g_sun[1], -1.0F, 1.0F)) * 57.2957795F;
  const float moonElev = asinf(clampf(g_moon[1], -1.0F, 1.0F)) * 57.2957795F;
  // Below -10 degrees a body stops being drawn - the same rule the
  // baked SCENE_SUN_R / SCENE_MOON_R use, so a setting sun slides out
  // of view instead of vanishing whole.
  g_sunRad = sunElev < -10.0F ? 0.0F : DAYCYCLE_SUN_RADS[scene];
  g_moonRad = moonElev < -10.0F ? 0.0F : DAYCYCLE_MOON_RADS[scene];
  // The twilight handover, zenith term and all - see ambience.cpp for
  // why the 4*w*(1-w) pull is not optional.
  float w = clampf((sunElev + 6.0F) / 12.0F, 0.0F, 1.0F);
  w = w * w * (3.0F - 2.0F * w);
  // The dominant body OWNS the direction - never a blend of the two.
  // They are near-opposite at the crossover, so a weighted sum
  // cancels (a 180-degree shadow flip) and rescuing it with a zenith
  // term points the light straight up (shadows vanish, then come
  // back from the wrong side). g_shadowFade below is what makes the
  // switch invisible instead. See ambience::evaluate - the twin.
  float L[3];
  for (int i = 0; i < 3; ++i) L[i] = w >= 0.5F ? g_sun[i] : g_moon[i];
  {
    const float sf = fabsf(2.0F * w - 1.0F);
    g_shadowFade = sf * sf * (3.0F - 2.0F * sf);
  }
  {
    const float l = sqrtf(L[0] * L[0] + L[1] * L[1] + L[2] * L[2]);
    if (l > 1e-6F) {
      L[0] /= l, L[1] /= l, L[2] /= l;
    } else {
      L[0] = 0.0F, L[1] = 1.0F, L[2] = 0.0F;
    }
  }
  const float minY = 0.0871557F;  // sin(5 degrees)
  if (L[1] < minY) {
    const float hl = sqrtf(L[0] * L[0] + L[2] * L[2]);
    const float want = sqrtf(1.0F - minY * minY);
    if (hl > 1e-5F) {
      L[0] = L[0] / hl * want;
      L[2] = L[2] / hl * want;
    }
    L[1] = minY;
  }
  // ...and never ON the pole: a steeply authored arc peaks within a
  // degree of straight up, and M4x4::lookAt's hardcoded world-up
  // makes that direction degenerate every basis built from it - the
  // projected shadows' light camera above all.
  const float maxY = 0.99939F;  // sin(88 deg), ambience::kMaxLightElevation
  if (L[1] > maxY) {
    const float hl = sqrtf(L[0] * L[0] + L[2] * L[2]);
    const float want = sqrtf(1.0F - maxY * maxY);
    if (hl > 1e-5F) {
      L[0] = L[0] / hl * want;
      L[2] = L[2] / hl * want;
    } else {
      L[0] = want;
      L[2] = 0.0F;
    }
    L[1] = maxY;
  }
  for (int i = 0; i < 3; ++i) g_light[i] = L[i];
  // Moon roll: the sun projected into the disc's plane, so the lit
  // limb keeps facing the sun (the disc is baked lit-side-to-+X).
  {
    float rx = g_moon[2], rz = -g_moon[0];
    const float rl = sqrtf(rx * rx + rz * rz);
    if (rl < 1e-5F) {
      rx = 1.0F, rz = 0.0F;
    } else {
      rx /= rl, rz /= rl;
    }
    const float ux = g_moon[1] * rz;
    const float uy = -g_moon[0] * rz + g_moon[2] * rx;
    const float uz = -g_moon[1] * rx;
    const float sx = g_sun[0] * rx + g_sun[2] * rz;
    const float sy = g_sun[0] * ux + g_sun[1] * uy + g_sun[2] * uz;
    g_moonRoll = atan2f(sy, sx);
  }
  // ambience::driftGrade. Identity when the clock sits on the hour
  // the geometry was baked at, which is the property that makes this
  // safe to leave on.
  if (!gradeOn(scene)) {
    g_gain[0] = g_gain[1] = g_gain[2] = 1.0F;
    g_lift[0] = g_lift[1] = g_lift[2] = 0.0F;
    g_comp[0] = g_comp[1] = g_comp[2] = 1.0F;
    g_mixAmount = 0.0F;
    return;
  }
  DayKeyData bk = DAY_KEYS[0];
  sampleKeys(scene, DAYCYCLE_BAKEDS[scene], bk);
  const float lit = (bk.amb + 0.5F * bk.dif) * bk.bright;
  const float want = (k.amb + 0.5F * k.dif) * k.bright;
  const float ratio = clampf(lit > 1e-4F ? want / lit : 1.0F, 0.15F, 2.0F);
  for (int i = 0; i < 3; ++i) {
    const float cb = bk.lit[i] < 0.02F ? 0.02F : bk.lit[i];
    g_gain[i] = clampf(ratio * (0.45F + 0.55F * (k.lit[i] / cb)),
                       0.5F, 2.0F);  // ambience::kMinDriftGain
    g_lift[i] = clampf(k.sky[i] * 0.06F * (1.0F - ratio), 0.0F, 0.12F);
    g_mixColor[i] = k.sky[i];
  }
  g_mixAmount = clampf(0.30F * (1.0F - ratio) +
                           (ratio > 1.0F ? 0.10F * (ratio - 1.0F) : 0.0F),
                       0.0F, 0.35F);
  for (int i = 0; i < 3; ++i)
    g_comp[i] = clampf(g_gain[i] > 1e-4F ? 1.0F / g_gain[i] : 1.0F, 1.0F, 2.0F);
}

// Called on every scene load: park the clock at the authored hour so
// the first frame of a scene matches what the editor previewed.
inline void reset(int scene) {
  if (!active(scene)) return;
  evaluate(scene, DAYCYCLE_STARTS[scene]);
}

// One frame. dt is real seconds; DAYCYCLE_DAYLEN is how many of them
// a whole 24 h takes.
inline void tick(int scene, float dt) {
  if (!active(scene)) return;
  const float len = DAYCYCLE_DAYLENS[scene];
  if (len > 0.001F) g_hour = wrap24(g_hour + dt * (24.0F / len));
  evaluate(scene, g_hour);
}

